    task_entry = {
        "id": "queue_audit_001",
        "source_draft_id": "draft_audit_001",
        "source_failure_norm_key": "sandbox_task|pick_up_object|pick_up|object_state|object_state",
        "semantic_key": "object_interaction",
        "task_state": "created",
    }
    task = build_review_task_trace(task_entry)
